const menu=document.querySelector('.menu');const nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close':'Menu';nav.classList.toggle('open',open)});nav.addEventListener('click',event=>{if(event.target.closest('a')){menu.setAttribute('aria-expanded','false');menu.textContent='Menu';nav.classList.remove('open')}});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&nav.classList.contains('open')){menu.click();menu.focus()}});
